const orders = items[0].json || [];
let totalRevenue = 0;
let ordersCount = 0;
let refundsCount = 0;
let refundsAmount = 0;
let codCount = 0;
let codAmount = 0;
let pendingCount = 0;
let productsMap = {};
let categoriesMap = {};

orders.forEach(order => {
  const status = order.status;
  if (status === 'refunded') {
    refundsCount++;
    refundsAmount += parseFloat(order.total);
  } else if (status === 'pending') {
    pendingCount++;
  } else if (status === 'completed' || status === 'processing') {
    ordersCount++;
    totalRevenue += parseFloat(order.total);

    if (order.payment_method === 'cod') {
      codCount++;
      codAmount += parseFloat(order.total);
    }

    order.line_items.forEach(item => {
      productsMap[item.name] = (productsMap[item.name] || 0) + item.quantity;
    });
  }
});

const topProducts = Object.entries(productsMap)
  .sort((a,b) => b[1] - a[1])
  .slice(0, 3)
  .map(e => `${e[0]} (x${e[1]})`)
  .join(', ') || 'None';

const averageOrderValue = ordersCount > 0 ? (totalRevenue / ordersCount).toFixed(2) : 0;

return [{
  json: {
    reportDate: new Date(Date.now() - 86400000).toISOString().split('T')[0],
    revenue: totalRevenue.toFixed(2),
    ordersCount,
    averageOrderValue,
    topProducts,
    refundsCount,
    refundsAmount: refundsAmount.toFixed(2),
    codCount,
    codAmount: codAmount.toFixed(2),
    pendingCount
  }
}];

